import React, { useState, useEffect } from "react";
import { watchlist as initialList } from "../data/data"; // your static list

export default function LiveWatchlist() {
  const [stocks, setStocks] = useState(initialList);

  useEffect(() => {
    const interval = setInterval(() => {
      setStocks((prevStocks) =>
        prevStocks.map((stock) => {
          // random change between -2% and +2%
          const changePercent = (Math.random() * 4 - 2).toFixed(2);
          const newPrice =
            stock.price + (stock.price * changePercent) / 100;

          return {
            ...stock,
            price: parseFloat(newPrice.toFixed(2)),
            percent:
              (changePercent > 0 ? "+" : "") + changePercent + "%",
            isDown: changePercent < 0,
          };
        })
      );
    }, 1000); // update every 1 second

    return () => clearInterval(interval);
  }, []);

  return (
    <div className="watchlist">
      <h2>Live Watchlist</h2>
      <table>
        <thead>
          <tr>
            <th>Stock</th>
            <th>Price (₹)</th>
            <th>Change (%)</th>
          </tr>
        </thead>
        <tbody>
          {stocks.map((stock, index) => (
            <tr
              key={index}
              style={{ color: stock.isDown ? "red" : "green" }}
            >
              <td>{stock.name}</td>
              <td>{stock.price}</td>
              <td>{stock.percent}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}
